def build_meta_prompt(context):
    evidence = context.get('evidence_ids', [])
    round_index = context.get('round', 0)
    slot = context.get('slot', 0)
    ranked = []
    for key in ('native', 'bootstrap/initial-incumbent'):
        if key in evidence:
            ranked.append(key)
    for key in evidence:
        if key not in ranked:
            ranked.append(key)
