{"source":"def build_prompt(context):
    parents = context['parent_ids']
    evidence = context['evidence_ids']
    slot = context['slot']
    evidence_map = context.get('evidence', {})
    feasible = []
    infeasible = []
    for eid in evidence:
        record = evidence_map.get(eid, {})
        status = record.get('status', '') if record else ''
        if status == 'feasible':
            feasible.append(eid)
        else:
            infeasible.append(eid)
    ordered = feasible[:2] + infeasible[:1] + feasible[2:] + infeasible[1:]
    chosen = []
    for eid in ordered:
        if eid not in chosen and len(chosen) < 4:
            chosen.append(eid)
    if not chosen:
        chosen = evidence[:3]
    if slot == 0:
        if len(parents) >= 2:
            operator = 'crossover'
            selected_parents = parents[:2]
        elif parents:
            operator = 'mutate'
            selected_parents = parents[:1]
        else:
            operator = 'construct'
            selected_parents = []
        rule = 0
        guidance = 'Revise slot 0 away from a fresh construct: use archived parent guidance and evidence ordered to keep feasible cases first, with one infeasible transfer failure as a repair signal. Emphasize safe ownership/placement and a fallback when no direct transfer to the attention rank is available.'
    elif parents and slot % 2 == 1:
        operator = 'mutate'
        selected_parents = parents[:1]
        rule = 0
        guidance = 'Keep the mutation path but change the evidence mix to feasible-first plus a transfer-failure repair signal; target ownership/eviction rules that can preserve a safe route to the attention rank.'
    else:
        operator = 'mutate' if parents else 'construct'
        selected_parents = parents[-1:] if parents else []
        rule = 0
        guidance = 'Use archived parent evidence with feasible cases prioritized and one infeasible transfer failure retained, so the rule includes a safe destination fallback.'
    return str({'operator': operator, 'parents': selected_parents, 'evidence': chosen[:4], 'rule': rule, 'guidance': guidance})

